const session=R.resolveSession(user,localStorage),assignment=session.activeAssignment,identity={id:user.uid||user.username||'',name:user.label||user.nama||user.displayName||user.username||'Konselor'};
if(session.activeRole!=='KONSELOR'||!['PEMULA','MADYA'].includes(assignment?.level)||!['PUTRA','PUTRI'].includes(assignment?.unit))throw new Error('Akses Konselor tidak tersedia untuk akun ini.');
const $=id=>document.getElementById(id),view=new URLSearchParams(location.search).get('view')||'cases';
const copy={cases:['KASUS MASUK','Kasus Masuk','Periksa dan tangani kasus santri.','▤'],book:['BUKU KONSELING','Buku Konseling','Riwayat konseling setiap santri.','▣'],evaluation:['EVALUASI PELANGGARAN','Evaluasi Pelanggaran','Analisis pelanggaran pekanan dan bulanan.','▥'],warnings:['SURAT PERINGATAN','Surat Peringatan','Terbitkan dan lihat riwayat SP santri.','▧']};
const warningRoot='cahaya_app/surat_peringatan_santri',warningPhotoRoot='cahaya_app/foto_sp_santri';
let records=[],visible=[],legacyBook={},selectedIds=new Set(),roster=new Map(),rosterNames=new Map(),warningRows=[],busy=false,processing=[],processIndex=0,decisions=new Map(),counselingRows=[],groupSessionId='',bookRows=[],selectedStudent='',periodMode='WEEK',caseFilter='all';
