function bookUnit(x){const unit=C.norm(x.unit||x.unitAsrama||'');return unit?unit===assignment.unit:roster.has(C.nameKey(x.santri||x.namaSantri||''))}
async function loadBook(){const generation=++loadGeneration.book;loadStatus.book='loading';selectedStudent='';state('Memuat Buku Konseling…');renderBookStudents();try{await loadRoster();const today=C.jakartaDate(),[reports,program,learning,book]=await Promise.all([scoped(C.ROOT,'tanggal','2019-01-01',today),scoped(C.PROGRAM_ATTENDANCE_ROOT,'tanggal','2019-01-01',today),scoped(C.LEARNING_ATTENDANCE_ROOT,'tanggal','2019-01-01',today),get(ref(db,'cahaya_app/buku_kasus_konselor')).catch(error=>{console.warn('Buku lama tidak terbaca:',error);return{val:()=>({})}})]);ctx?.assertCurrent();if(generation!==loadGeneration.book)return;const cases=normalizeSources(reports,program,learning),legacy=Object.fromEntries(Object.entries(book.val()||{}).filter(([,x])=>bookUnit(x)));legacyBook=legacy;bookRows=M.bookEntries(cases,legacy);loadStatus.book='ready';renderBookStudents();state(bookRows.length+' catatan konseling ditemukan.')}catch(error){if(generation!==loadGeneration.book)return;console.error(error);loadStatus.book='error';renderBookStudents();state('Buku Konseling belum dapat dimuat.','error')}}
function renderBookStudents(){if(loadStatus.book!=='ready'){const markup=loadStatus.book==='error'?loadErrorMarkup('Buku Konseling belum dapat dimuat. Periksa koneksi lalu buka kembali menu ini.'):loadingMarkup('Memuat Buku Konseling…');$('bookStudents').innerHTML=markup;$('bookHistory').innerHTML=markup;return}const q=C.nameKey($('bookSearch').value),students=new Map();for(const row of bookRows){if(q&&!row.studentKey.includes(q))continue;const old=students.get(row.studentKey)||{name:row.student,key:row.studentKey,count:0};old.count++;students.set(row.studentKey,old)}$('bookStudents').innerHTML=students.size?[...students.values()].sort((a,b)=>a.name.localeCompare(b.name,'id')).map(x=>'<button class="ks-book-student '+(selectedStudent===x.key?'active':'')+'" data-book-student="'+esc(x.key)+'" type="button"><strong>'+esc(x.name)+'</strong><small>'+x.count+' catatan konseling</small></button>').join(''):'<div class="ks-empty">Belum ada santri sesuai pencarian.</div>';if(selectedStudent)renderBookHistory();else $('bookHistory').innerHTML='<div class="ks-empty">Pilih santri untuk melihat riwayat konseling.</div>'}
