function formatDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?String(value||'Tanggal belum tersedia'):new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(date)}
function fillPeriodButtons(){document.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x.dataset.period===periodMode))}
async function evaluationRows(range){
 const [reports,program,learning,actionsByEvent,actionsByProcessing]=await Promise.all([
  scoped(C.ROOT,'tanggal',C.shiftDate(range.start,-1),C.shiftDate(range.end,1)),
  scoped(C.PROGRAM_ATTENDANCE_ROOT,'tanggal',range.start,range.end),
  scoped(C.LEARNING_ATTENDANCE_ROOT,'tanggal',range.start,range.end),
  optionalScoped('cahaya_app/laporan_penindakan','tanggalKejadian',range.start,range.end),
  optionalScoped('cahaya_app/laporan_penindakan','tanggalPenindakan',range.start,range.end)
 ]);
 const primary=normalizeSources(reports,program,learning),ids=new Set(primary.filter(x=>M.proven(x)||M.cleared(x)).map(x=>x.id));
 const actions={...actionsByEvent.val(),...actionsByProcessing.val()};
 const legacy=Object.entries(actions).filter(([,x])=>!ids.has(String(x.sumberCaseId||''))&&bookUnit(x)).map(([id,x])=>enrich(C.normalizeCase({...x,tipe:'Lapor Pelanggaran',tanggal:x.tanggalKejadian||x.tanggalPenindakan,dilaporkan:x.santri||x.namaSantri,statusPenanganan:x.status||'SELESAI',kodePelanggaran:x.kodePelanggaran||x.jenisPelanggaran||'PELANGGARAN_LAIN'},'legacy_'+id)));
 return [...primary,...legacy];
}
function formatComparisonPeriod(range){
 const start=new Date(range.start+'T12:00:00Z');
 if(range.mode==='MONTH')return new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric',timeZone:'UTC'}).format(start);
 const end=new Date(range.end+'T12:00:00Z'),format=new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',timeZone:'UTC'});
 return format.format(start)+' – '+format.format(end);
}
function renderComparison(results,mode){
 const max=Math.max(1,...results.map(x=>x.total));
 const title=mode==='WEEK_4'?'Perbandingan 4 Pekan Terakhir':'Perbandingan 4 Bulan Terakhir';
 $('comparisonPanel').innerHTML='<h2>'+title+'</h2><p>Kasus terbukti dikelompokkan menurut tanggal kejadian. Periode terbaru dapat masih berjalan.</p><div class="ks-comparison-list">'+results.map((result,index)=>{
  const delta=index?result.total-results[index-1].total:null,change=delta===null?'Awal perbandingan':delta===0?'Sama dengan periode sebelumnya':(delta>0?'+':'')+delta+' dari periode sebelumnya';
  return '<article class="ks-comparison-row"><div class="ks-comparison-period"><strong>'+esc(formatComparisonPeriod(result.period))+'</strong><small>'+esc(result.period.start)+' – '+esc(result.period.end)+'</small><span class="ks-comparison-change">'+esc(change)+'</span></div><div class="ks-comparison-number" aria-label="'+result.total+' kasus terbukti">'+result.total+'</div><div class="ks-comparison-bar" aria-hidden="true"><span style="width:'+Math.round(result.total/max*100)+'%"></span></div><div class="ks-comparison-stat">'+result.students+'<small>Santri unik</small></div><div class="ks-comparison-stat">'+result.kinds+'<small>Jenis</small></div><div class="ks-comparison-stat">'+result.finished+'<small>Selesai ditangani</small></div></article>';
 }).join('')+'</div>';
}
async function loadEvaluation(){
 const generation=++evaluationGeneration,date=$('periodDate').value||C.jakartaDate(),comparing=periodMode==='WEEK_4'||periodMode==='MONTH_4';
 const baseMode=periodMode.startsWith('MONTH')?'MONTH':'WEEK',periods=comparing?M.comparisonPeriods(baseMode,date):[M.period(baseMode,date)];
 const range={start:periods[0].start,end:periods[periods.length-1].end};
 fillPeriodButtons();$('periodLabel').textContent=range.start+' — '+range.end+' · '+assignment.unit;
 $('comparisonPanel').hidden=!comparing;$('evalMetrics').hidden=comparing;$('evalGrid').hidden=comparing;$('trendPanel').hidden=comparing;
 if(comparing)$('comparisonPanel').innerHTML=loadingMarkup('Memuat perbandingan periode…');
 else{$('evalMetrics').innerHTML=loadingMarkup('Menghitung pelanggaran terbukti…');$('topTypes').innerHTML='';$('topStudents').innerHTML='';$('trendChart').innerHTML=''}
 state(comparing?'Memuat perbandingan periode…':'Menghitung pelanggaran terbukti…');
 try{
  await loadRoster();const rows=await evaluationRows(range);ctx?.assertCurrent();if(generation!==evaluationGeneration)return;
  if(comparing){const results=periods.map(item=>M.evaluation(rows,item));renderComparison(results,periodMode);state('Perbandingan '+results.length+' periode berdasarkan kasus terbukti.')}else{const result=M.evaluation(rows,periods[0]);renderEvaluation(result);state('Evaluasi berdasarkan '+result.total+' kasus terbukti pada periode terpilih.')}
 }catch(error){if(generation!==evaluationGeneration)return;console.error(error);if(comparing)$('comparisonPanel').innerHTML=loadErrorMarkup('Perbandingan belum dapat dimuat. Periksa koneksi lalu coba lagi.');else $('evalMetrics').innerHTML=loadErrorMarkup('Evaluasi belum dapat dimuat. Periksa koneksi lalu coba lagi.');state('Evaluasi Pelanggaran belum dapat dimuat.','error')}
}
function renderEvaluation(result){const values=[[result.total,'Kasus Terbukti'],[result.students,'Santri Unik'],[result.kinds,'Jenis Pelanggaran'],[result.finished,'Selesai Ditangani']];$('evalMetrics').innerHTML=values.map(([n,label])=>'<div class="ks-metric"><b>'+n+'</b><span>'+label+'</span></div>').join('');$('topTypes').innerHTML=result.types.length?result.types.slice(0,10).map((x,i)=>'<div class="ks-eval-row"><strong>'+(i+1)+'.</strong><span>'+esc(x.name)+'</span><b>'+x.count+'</b></div>').join(''):'<div class="ks-empty">Belum ada pelanggaran terbukti.</div>';$('topStudents').innerHTML=result.studentRows.length?result.studentRows.slice(0,10).map((x,i)=>'<div class="ks-eval-row"><strong>'+(i+1)+'.</strong><span>'+esc(x.student)+'<small>'+esc(x.group||'Kelas/asrama belum tercatat')+' · '+esc(x.kinds.join(', '))+'</small></span><b>'+x.count+'</b></div>').join(''):'<div class="ks-empty">Belum ada santri dengan pelanggaran terbukti.</div>';const max=Math.max(1,...result.trend.map(x=>x.count));$('trendChart').innerHTML=result.trend.map(x=>'<div class="ks-trend-col"><div class="ks-trend-bar-wrap"><div class="ks-trend-bar" style="height:'+Math.max(3,Math.round(x.count/max*105))+'px" title="'+esc(x.label)+': '+x.count+'"></div></div><div><b>'+x.count+'</b><small>'+esc(x.label)+'</small></div></div>').join('')}
function warningInScope(row){const key=C.nameKey(row.namaSantri||''),group=roster.get(key);if(!group)return false;return !row.usrah||row.usrah==='Belum Terpetakan'||row.usrah===group}
function warningResource(group){return{unit:assignment.unit,usrahId:'USRAH_'+String(group).replace(/\D/g,'')}}
function warningAllowed(group){return Boolean(group&&R.authorize(session,'case.warning',warningResource(group))&&(!ctx||ctx.can('case.warning',warningResource(group))))}
function renderWarnings(){if(loadStatus.warnings!=='ready'){$('warningList').innerHTML=loadStatus.warnings==='error'?loadErrorMarkup('Surat Peringatan belum dapat dimuat. Periksa koneksi lalu buka kembali menu ini.'):loadingMarkup('Memuat Surat Peringatan…');return}const q=C.nameKey($('warningSearch').value),rows=warningRows.filter(row=>!q||[row.namaSantri,row.deskripsiPelanggaran,row.jenisSP].some(value=>C.nameKey(value).includes(q)));$('warningList').innerHTML=rows.length?rows.map(row=>'<article class="ks-warning-card"><div class="ks-warning-main"><span class="ks-warning-badge">SP '+esc(row.jenisSP||1)+'</span><h2>'+esc(row.namaSantri||'Santri')+'</h2><p>'+esc(row.deskripsiPelanggaran||'Deskripsi belum tercatat.')+'</p><small>'+esc(row.usrah||roster.get(C.nameKey(row.namaSantri))||'')+' · Diberikan oleh '+esc(row.diberikanOleh||'Konselor')+'</small>'+(row.adaFoto?'<button class="ks-warning-photo" type="button" data-warning-photo="'+esc(row.idSP||row.id)+'">Lihat foto SP ↗</button>':'')+'</div><div class="ks-warning-date"><b>'+esc(row.tanggal||'')+'</b><span>'+esc(row.status||'AKTIF')+'</span></div></article>').join(''):'<div class="ks-empty">Belum ada Surat Peringatan sesuai pencarian dan unit Anda.</div>';state(rows.length+' Surat Peringatan ditampilkan.')}
async function loadWarnings(){const generation=++loadGeneration.warnings;loadStatus.warnings='loading';state('Memuat Surat Peringatan…');renderWarnings();try{await loadRoster();const snap=await get(query(ref(db,warningRoot),orderByChild('dibuatPada'),limitToLast(500)));ctx?.assertCurrent();if(generation!==loadGeneration.warnings)return;warningRows=Object.entries(snap.val()||{}).map(([id,row])=>({id,...(row||{})})).filter(warningInScope).sort((a,b)=>(Number(b.dibuatPada)||0)-(Number(a.dibuatPada)||0));loadStatus.warnings='ready';renderWarnings()}catch(error){if(generation!==loadGeneration.warnings)return;console.error(error);loadStatus.warnings='error';renderWarnings();state('Surat Peringatan belum dapat dimuat.','error')}}
function openWarningForm(){const options=[...rosterNames.entries()].sort((a,b)=>a[1].localeCompare(b[1],'id')).map(([,name])=>'<option value="'+esc(name)+'"></option>').join('');openSheet('<div class="ks-sheet-head"><div><span class="ks-progress-text">PEMBINAAN SANTRI</span><h2 id="workflowTitle">Berikan Surat Peringatan</h2><p>Catat SP pada data santri di unit Anda.</p></div><button class="ks-sheet-close" type="button" data-action="close" aria-label="Tutup">×</button></div><form id="warningForm"><div class="ks-simple-field"><label for="warningStudent">Nama Santri</label><input class="ks-input" id="warningStudent" list="warningStudentList" autocomplete="off" required placeholder="Ketik atau pilih nama santri"><datalist id="warningStudentList">'+options+'</datalist></div><div class="ks-simple-field"><label for="warningType">Jenis SP</label><select id="warningType"><option value="1">SP 1</option><option value="2">SP 2</option></select></div><div class="ks-simple-field"><label for="warningDescription">Deskripsi Pelanggaran</label><textarea id="warningDescription" required placeholder="Jelaskan pelanggaran yang menjadi dasar pemberian SP."></textarea></div><div class="ks-simple-field"><label for="warningPhoto">Foto SP (opsional)</label><input id="warningPhoto" type="file" accept="image/jpeg,image/png,image/webp"></div><div class="ks-sheet-actions"><button class="ks-btn secondary" type="button" data-action="close">Batal</button><button class="ks-btn" id="saveWarningBtn" type="submit">Simpan SP</button></div></form>')}
function compressWarningPhoto(file){return new Promise((resolve,reject)=>{if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>8*1024*1024)return reject(new Error('Gunakan foto JPG, PNG, atau WebP maksimal 8 MB.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Foto tidak dapat dibaca.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Foto tidak valid.'));img.onload=()=>{const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78))};img.src=reader.result};reader.readAsDataURL(file)})}
async function saveWarning(event){
 event.preventDefault();
 if(busy)return;
 const entered=$('warningStudent').value.trim(),key=C.nameKey(entered),group=roster.get(key),name=rosterNames.get(key);
 const kind=Number($('warningType').value),description=$('warningDescription').value.trim(),file=$('warningPhoto').files?.[0];
 if(!name||!group)return toast('Pilih santri yang terdaftar pada unit Anda.');
 if(!warningAllowed(group))return toast('Akun ini belum berwenang menerbitkan SP untuk santri tersebut.');
 if(![1,2].includes(kind)||!description)return toast('Lengkapi jenis SP dan deskripsi pelanggaran.');
 busy=true;$('saveWarningBtn').disabled=true;
 let created=null,photoSaved=false,warningSaved=false;
 try{
  ctx?.assertCurrent();
  const photo=file?await compressWarningPhoto(file):'',now=Date.now();
  ctx?.assertCurrent();if(!warningAllowed(group))throw new Error('Kewenangan SP telah berubah. Muat ulang halaman.');
  created=push(ref(db,warningRoot));
  const idSP=created.key,photoPath=photo?warningPhotoRoot+'/'+idSP:'';
  if(photo){await set(ref(db,photoPath),{dataUrl:photo,namaFile:file.name||'foto-sp',mime:'image/jpeg',dibuatPada:now});photoSaved=true}
  await set(created,{idSP,tanggal:C.jakartaDate(),namaSantri:name,namaSantriKey:key,usrah:group,
   deskripsiPelanggaran:description,jenisSP:kind,status:'AKTIF',adaFoto:Boolean(photo),fotoPath,
   diberikanOleh:identity.name,dibuatPada:now});
  warningSaved=true;busy=false;closeSheet();toast('SP '+kind+' untuk '+name+' berhasil disimpan.');await loadWarnings();
 }catch(error){
  if(photoSaved&&!warningSaved&&created)await remove(ref(db,warningPhotoRoot+'/'+created.key)).catch(cleanupError=>console.warn('Foto SP sementara belum dapat dibersihkan:',cleanupError));
  busy=false;console.error(error);toast(error.message||'Surat Peringatan belum dapat disimpan.');
 }finally{const button=$('saveWarningBtn');if(button)button.disabled=false}
}
async function openWarningPhoto(id){const row=warningRows.find(item=>(item.idSP||item.id)===id);if(!row||!warningInScope(row))return toast('Foto SP tidak tersedia pada unit Anda.');try{const snap=await get(ref(db,warningPhotoRoot+'/'+id));ctx?.assertCurrent();const url=snap.val()?.dataUrl||'';if(!/^data:image\/(?:jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(url))throw new Error('Format foto SP tidak didukung.');openSheet('<div class="ks-sheet-head"><div><h2 id="workflowTitle">Foto Surat Peringatan</h2><p>'+esc(row.namaSantri||'Santri')+'</p></div><button class="ks-sheet-close" type="button" data-action="close" aria-label="Tutup">×</button></div><img class="ks-warning-image" alt="Foto SP '+esc(row.namaSantri||'Santri')+'" src="'+url+'">')}catch(error){console.error(error);toast(error.message||'Foto SP belum dapat dibuka.')}}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action,admission=event.target.closest('[data-admission]'),outcome=event.target.closest('[data-outcome]'),periodButton=event.target.closest('[data-period]'),bookStudent=event.target.closest('[data-book-student]'),warningPhoto=event.target.closest('[data-warning-photo]');if(action==='close')closeSheet(true);if(action==='tabayyun-next')nextTabayyun();if(action==='send-escalation')sendEscalation();if(action==='escalation-toggle')$('escalationPanel').hidden=!$('escalationPanel').hidden;if(action==='counseling-back'){processIndex=Math.max(0,processing.length-1);renderTabayyun()}if(admission){document.querySelectorAll('[data-admission]').forEach(x=>x.classList.toggle('selected',x===admission));$('denialFields').hidden=admission.dataset.admission!=='TIDAK_MENGAKUI'}if(outcome)document.querySelectorAll('[data-outcome]').forEach(x=>x.classList.toggle('selected',x===outcome));if(periodButton){periodMode=periodButton.dataset.period;loadEvaluation()}const caseFilterButton=event.target.closest('[data-case-filter]');if(caseFilterButton){caseFilter=caseFilterButton.dataset.caseFilter;renderCases()}if(bookStudent){selectedStudent=bookStudent.dataset.bookStudent;renderBookStudents()}if(warningPhoto)openWarningPhoto(warningPhoto.dataset.warningPhoto)});
document.addEventListener('change',event=>{if(event.target.matches('[data-case-id]')){event.target.checked?selectedIds.add(event.target.dataset.caseId):selectedIds.delete(event.target.dataset.caseId);selectCount()}if(event.target.id==='selectAllCases'){visible.forEach(c=>event.target.checked?selectedIds.add(c.id):selectedIds.delete(c.id));renderCases()}if(event.target.id==='periodDate')loadEvaluation();if(event.target.id==='noConsequence')$('sharedConsequence').disabled=event.target.checked});
$('caseSearch').addEventListener('input',renderCases);$('bookSearch').addEventListener('input',renderBookStudents);$('warningSearch').addEventListener('input',renderWarnings);$('newWarningBtn').addEventListener('click',openWarningForm);$('processBtn').addEventListener('click',startProcessing);document.addEventListener('submit',event=>{if(event.target.id==='counselingForm')saveCounseling(event);if(event.target.id==='warningForm')saveWarning(event)});$('backBtn').onclick=()=>{if(parent!==window&&typeof parent.openAuthorizedMenu==='function')parent.openAuthorizedMenu('menu-home');else history.back()};
const selectedView=copy[view]?view:'cases';document.body.dataset.view=selectedView;$('eyebrow').textContent=copy[selectedView][0];$('pageTitle').textContent=copy[selectedView][1];$('pageSubtitle').textContent=copy[selectedView][2];$('heroIcon').textContent=copy[selectedView][3];$('levelChip').textContent=assignment.level;$('unitChip').textContent=assignment.unit;$('roleChip').textContent='Konselor '+(assignment.level==='MADYA'?'Madya':'Pemula');$('casesSection').hidden=selectedView!=='cases';$('bookSection').hidden=selectedView!=='book';$('evaluationSection').hidden=selectedView!=='evaluation';$('warningsSection').hidden=selectedView!=='warnings';$('periodDate').value=C.jakartaDate();
if(selectedView==='cases')loadCases();else if(selectedView==='book')loadBook();else if(selectedView==='evaluation')loadEvaluation();else loadWarnings();
